/* End-to-end local flows. Public artwork is local; provider/media credentials are never loaded. */
(() => {
  'use strict';
  const P=window.TVPrototype, D=window.TV_CATALOG;
  const {S,app,esc,icon,btn,brand,sidebar,go,render,focus,openPanel,closePanel,renderPanel,toast,announce,channels}=P;
  // m1 is excluded: the provider labels it Dune Part Two, but its artwork depicts Dune (2021).
  // Keep the sanitized evidence in the catalog; never silently relabel a provider item.
  const movies=D.movies.filter(x=>x.id!=='m1'), shows=D.series, hero=movies.find(x=>x.id==='m3');
  Object.assign(P.paths,{search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',lock:'M6 10h12v11H6Zm2 0V6a4 4 0 0 1 8 0v4m-4 4v3',pause:'M8 4v16M16 4v16',keyboard:'M2 5h20v14H2ZM5 9h1m3 0h1m3 0h1m3 0h1M5 13h1m3 0h1m3 0h1m3 0h1M8 16h8',replay:'M4 7v6h6M4 13a8 8 0 1 1 2 6'});
  Object.assign(S,{catalogFilter:'Tümü',showId:'s1',movieId:'m2',season:1,query:'',searchType:'Tümü',favType:'Kanallar',history:{},detailReturn:{view:'movies',focus:'movie-m2'},vodReturn:{view:'movie',focus:'detail-play'},media:null,playing:false,unlocked:new Set(),parental:true,pin:'',pinError:'',pending:null,keyboardField:'url',guideAnchor:42,program:null,missingArt:false,nextSeconds:10});
  const programs=['Belgesel kuşağı','Akşam kuşağı','Müzik saati','Spor gündemi',null,'Haber kuşağı'];
  channels.forEach((ch,i)=>Object.assign(ch,D.channels[i],{program:programs[i] ? programs[i]+' · örnek' : null,next:programs[i]?'Sonraki program · örnek':null,description:'Program saatleri bu etkileşim denemesi için örnektir. Güncel yayın bilgisi değildir.',radio:false,locked:i===3}));
  Object.assign(P.labels,{guide:'TV-021 · Rehber',movies:'TV-030 · Filmler',movie:'TV-031 · Film ayrıntısı',series:'TV-040 · Diziler',show:'TV-041 · Sezon ve bölümler',vod:'TV-051 · Film/dizi oynatıcı',search:'TV-060 · Arama'});
  const findMovie=id=>movies.find(x=>x.id===id),findShow=id=>shows.find(x=>x.id===id);
  const time=seconds=>{const s=Math.max(0,Math.floor(seconds));return `${Math.floor(s/3600)?Math.floor(s/3600)+':':''}${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
  const duration=item=>`${Math.round(item.duration/60)} dk`;
  const sourceName=P.sourceName;
  const progress=id=>S.history[id]?.position||0;
  const getItem=id=>findMovie(id)||findShow(id)||channels.find(x=>x.id===id);
  const locked=item=>item.locked&&S.parental&&!S.unlocked.has(item.id);
  function requestPin(pending){S.pinOrigin={panel:S.panel,focus:document.activeElement?.dataset.focus};S.pending=pending;S.pin='';S.pinError='';openPanel('pin');}
  function cancelPin(){const origin=S.pinOrigin;S.pending=null;S.pin='';S.pinError='';S.pinOrigin=null;closePanel();if(origin?.panel){openPanel(origin.panel);renderPanel(origin.focus);}}
  function gate(item,callback){if(locked(item)){requestPin({id:item.id,run:callback});return false;}callback();return true;}
  const art=item=>S.missingArt?'':item.backdrop||item.poster||'';
  function poster(item,kind,prefix=''){const lock=locked(item);return `<button class="poster-card" data-focus="${prefix}${kind}-${item.id}" data-action="open-${kind}" data-id="${item.id}" aria-label="${esc(item.title)}${lock?' · PIN gerekli':''}"><span class="poster-art"><span class="art-fallback">${icon(lock?'lock':'film')}<span>${lock?'PIN gerekli':'Kapak bulunamadı'}</span></span>${item.poster?`<img class="poster-image" src="${esc(item.poster)}" alt="${esc(item.title)} afişi" loading="lazy">`:''}${lock?`<span class="poster-lock">${icon('lock')} PIN</span>`:''}${progress(item.id)?`<span class="poster-progress" style="width:${Math.min(100,progress(item.id)/item.duration*100)}%"></span>`:''}</span><strong>${esc(item.title)}</strong><small>${esc(item.year|| (kind==='show'?'Dizi':'Film'))}${item.duration?' · '+duration(item):''}</small></button>`;}
  const availableMovies=()=>S.result==='partial'?[]:movies;
  const availableShows=()=>S.result==='partial'?[]:shows;
  const pendingCatalog=()=>`<div class="empty-block">${icon('folder')}<h2>Kütüphane henüz yüklenmedi.</h2><p>Canlı kanallar hazır. Film ve dizi bilgileri için tekrar deneyebilirsin.</p>${btn('pending-retry','retry-import','Tekrar dene','primary')}</div>`;
  function catalogItems(kind){const items=kind==='movie'?availableMovies():availableShows();return items.filter(x=>S.catalogFilter==='Tümü'||(S.catalogFilter==='Korumalı'?x.locked:!x.locked));}
  function catalog(kind){const items=catalogItems(kind),isMovie=kind==='movie';return `<section class="view shell">${sidebar(isMovie?'movies':'series')}<div class="page-body library"><div class="library-head"><div class="eyebrow">${sourceName()} · KÜTÜPHANEN</div><span class="muted">${items.length} içerik</span></div><h2>${isMovie?'Film gecesi burada başlar.':'Bir bölüm daha.'}</h2><div class="filters catalog-filters">${['Tümü','Açık içerikler','Korumalı'].map((name,i)=>`<button class="filter" data-focus="catalog-filter-${i}" data-action="catalog-filter" data-value="${name}" aria-pressed="${S.catalogFilter===name}">${name}</button>`).join('')}</div>${S.result==='partial'?pendingCatalog():`<div class="poster-grid">${items.map(x=>poster(x,kind)).join('')}</div>`}<p class="catalog-note">${isMovie?'Film':'Dizi'} adları ve görseller sağladığın katalogdan. Oynatma bu prototipte örnektir.</p></div></section>`;}
  function openDetail(kind,id,origin){const item=kind==='movie'?findMovie(id):findShow(id);gate(item,()=>{S.detailReturn={view:S.view,focus:origin||document.activeElement?.dataset.focus};if(kind==='movie'){S.movieId=id;go('movie');}else{S.showId=id;S.season=item.seasons[0]?.number||1;go('show');}});}
  function favoriteButton(item){return btn('detail-favorite','catalog-favorite',icon('star')+(S.favorites.has(item.id)?' Favoride':' Favori ekle'),'quiet',`data-id="${item.id}" aria-pressed="${S.favorites.has(item.id)}"`);}
  function detail(kind){const item=kind==='movie'?findMovie(S.movieId):findShow(S.showId),isMovie=kind==='movie';return `<section class="view content-detail" style="--detail-art:url('${esc(art(item))}')"><div class="detail-art"></div><div class="detail-scrim"></div><div class="topline"><button class="back-btn" data-focus="detail-back" data-action="detail-back">${icon('back')} Geri</button><span class="step">${isMovie?'FİLM':'DİZİ'}</span></div><div class="detail-copy"><span class="eyebrow">${esc(item.genre||'Kütüphanen')}</span><h1>${esc(item.title)}</h1><div class="metadata-line">${esc(item.year||'')}${isMovie?' · '+duration(item):' · '+item.seasons.length+' sezon örneği'}${isMovie&&Number(item.rating)>0?' · ★ '+Number(item.rating).toFixed(1):''}</div><p class="synopsis">${esc(item.description||'Bu içerik için açıklama bulunmuyor.')}</p><div class="actions">${isMovie?btn('detail-play','play-movie',icon('play')+(progress(item.id)>0&&progress(item.id)<item.duration?' Devam et · '+time(progress(item.id)):' Oynat'),'primary',`data-id="${item.id}"`):btn('show-continue','show-continue',icon('play')+' Bölüme devam et','primary')}${favoriteButton(item)}${item.description?btn('description','description','Açıklama','quiet'):''}${isMovie&&progress(item.id)>0?btn('restart-movie','restart-movie','Baştan izle','quiet'):''}</div>${isMovie?'<p class="detail-footnote">Ses ve altyazı seçenekleri oynatıcıda gösterilir.</p>':''}</div>${isMovie?`<div class="detail-poster"><img src="${esc(item.poster)}" alt="${esc(item.title)} afişi"></div>`:episodeSection(item)}</section>`;}
  function seasonData(){return findShow(S.showId).seasons.find(x=>x.number===S.season)||findShow(S.showId).seasons[0];}
  function episodeSection(show){const season=seasonData();return `<section class="episodes-area"><div class="season-row"><h3>Bölümler</h3>${show.seasons.map(s=>`<button class="filter" data-focus="season-${s.number}" data-action="season" data-value="${s.number}" aria-pressed="${S.season===s.number}">${s.number}. sezon</button>`).join('')}<span>İlk ${season.episodes.length} bölüm önizlemesi</span></div><div class="episode-grid">${season.episodes.length?season.episodes.map(e=>`<button class="episode-card" data-focus="ep-${e.id}" data-action="play-episode" data-id="${e.id}"><span class="episode-image"><img src="${esc(e.still||show.backdrop||show.poster)}" alt="${esc(e.title)}" loading="lazy"><span class="episode-number">${e.number}</span>${progress(e.id)?`<span class="poster-progress" style="width:${Math.min(100,progress(e.id)/e.duration*100)}%"></span>`:''}</span><strong>${esc(e.title)}</strong><small>${duration(e)}${progress(e.id)?' · '+time(progress(e.id))+' izlendi':''}</small></button>`).join(''):'<p>Bu sezonda henüz bölüm bulunmuyor.</p>'}</div></section>`;}
  function episodeById(id){for(const show of shows)for(const season of show.seasons)for(const episode of season.episodes)if(episode.id===id)return {show,season,episode};return null;}
  function firstResumeEpisode(){const list=findShow(S.showId).seasons.flatMap(x=>x.episodes);return list.find(x=>progress(x.id)>0&&progress(x.id)<x.duration)||list.find(x=>!progress(x.id))||list[0];}
  function playMovie(id,restart=false){const item=findMovie(id);gate(item,()=>{S.vodReturn={view:S.view==='movie'?'movie':S.view,focus:S.view==='movie'?'detail-play':document.activeElement?.dataset.focus};S.movieId=id;S.media={kind:'movie',id,title:item.title,art:art(item),duration:item.duration,position:restart||progress(id)>=item.duration?0:progress(id)};S.playing=true;S.controls=true;go('vod','vod-toggle');});}
  function playEpisode(id){const match=episodeById(id);if(!match)return;gate(match.show,()=>{S.vodReturn={view:'show',focus:'ep-'+id};S.showId=match.show.id;S.season=match.season.number;S.media={kind:'episode',id,showId:match.show.id,title:match.show.title,subtitle:`${S.season}. sezon · ${match.episode.number}. bölüm`,art:match.episode.still||art(match.show),duration:match.episode.duration,position:progress(id)>=match.episode.duration?0:progress(id)};S.playing=true;S.controls=true;go('vod','vod-toggle');});}
  function saveProgress(){if(S.media)S.history[S.media.id]={position:S.media.position,duration:S.media.duration,kind:S.media.kind,showId:S.media.showId};}
  function leaveVod(){saveProgress();S.playing=false;const dest=S.vodReturn;S.panel=null;go(dest.view,dest.focus);}
  function nextEpisode(){if(S.media?.kind!=='episode')return null;const list=findShow(S.media.showId).seasons.flatMap(x=>x.episodes),index=list.findIndex(x=>x.id===S.media.id);return list[index+1]||null;}
  function vod(){const m=S.media;return `<section class="view player vod ${S.controls?'':'hidden-controls'}" style="background-image:url('${esc(S.missingArt?'':m.art)}')"><button class="reveal-controls" data-focus="reveal" data-action="reveal" aria-label="Kontrolleri göster" ${S.controls?'disabled':''}></button><div class="player-top"><button class="back-btn" data-focus="vod-back" data-action="leave-vod">${icon('back')} Geri</button><span>${esc(m.title)}</span><span class="clock">20:42</span></div><div class="sample-watermark">Örnek oynatma · gerçek video yok</div><div class="program-title"><span class="eyebrow">${esc(m.subtitle||'FİLM')}</span><h1>${esc(m.title)}</h1></div><div class="player-controls"><div class="player-info"><span id="vod-current">${time(m.position)}</span><span>${time(m.duration)}</span></div><input class="seekbar" data-focus="seek" id="vod-seek" type="range" min="0" max="${m.duration}" step="1" value="${m.position}" aria-label="Oynatma konumu"><div class="player-actions"><div class="actions">${btn('vod-rewind','vod-seek',icon('left')+' 10 sn','quiet','data-value="-10"')}${btn('vod-toggle','vod-toggle',icon(S.playing?'pause':'play')+(S.playing?' Duraklat':' Oynat'),'primary')}${btn('vod-forward','vod-seek','10 sn '+icon('right'),'quiet','data-value="10"')}</div><div class="actions">${m.kind==='episode'&&nextEpisode()?btn('vod-next','vod-next','Sonraki bölüm '+icon('right')):''}${btn('tracks','tracks',icon('sound')+' Ses ve altyazı')}</div></div></div><span class="player-guide">${S.controls?'Geri: kontrolleri gizle':'OK: kontroller · Geri: ayrıntıya dön'}</span></section>`;}
  let lastTick=performance.now(),nextTimer;
  function finish(){if(S.view!=='vod')return;S.media.position=S.media.duration;saveProgress();S.playing=false;S.controls=true;S.nextSeconds=10;render('vod-toggle');openPanel('finished');if(nextEpisode()){clearInterval(nextTimer);nextTimer=setInterval(()=>{if(S.panel!=='finished'||S.view!=='vod'){clearInterval(nextTimer);return;}S.nextSeconds--;const timer=document.getElementById('next-timer');if(timer)timer.textContent=S.nextSeconds;if(S.nextSeconds<=0){clearInterval(nextTimer);playEpisode(nextEpisode().id);}},1000);}}
  setInterval(()=>{const now=performance.now(),elapsed=Math.min(1,(now-lastTick)/1000);lastTick=now;if(S.view!=='vod'||!S.playing||S.panel==='stream-error')return;S.media.position=Math.min(S.media.duration,S.media.position+elapsed);saveProgress();const current=document.getElementById('vod-current'),seek=document.getElementById('vod-seek');if(current)current.textContent=time(S.media.position);if(seek&&document.activeElement!==seek)seek.value=S.media.position;if(S.media.position>=S.media.duration)finish();},250);
  function favorites(){const items=S.favType==='Kanallar'?channels.filter(x=>S.favorites.has(x.id)):S.favType==='Filmler'?availableMovies().filter(x=>S.favorites.has(x.id)):availableShows().filter(x=>S.favorites.has(x.id));return `<section class="view shell">${sidebar('favorites')}<div class="page-body library"><h2>Favorilerin</h2><div class="filters catalog-filters">${['Kanallar','Filmler','Diziler'].map((name,i)=>`<button class="filter" data-focus="fav-filter-${i}" data-action="fav-filter" data-value="${name}" aria-pressed="${S.favType===name}">${name}</button>`).join('')}</div>${items.length?S.favType==='Kanallar'?`<div class="channel-grid">${items.map(ch=>P.card(ch,channels.indexOf(ch))).join('')}</div>`:`<div class="poster-grid">${items.map(x=>poster(x,S.favType==='Filmler'?'movie':'show','fav-')).join('')}</div>`:`<div class="empty-block">${icon('star')}<h2>Henüz favorin yok.</h2><p>Sevdiğin içerikleri ayrıntı ekranından ekleyebilirsin.</p>${btn('favorite-browse','favorite-browse','İçeriklere göz at','primary')}</div>`}</div></section>`;}
  function normalize(value){return value.toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i');}
  function matches(){const q=normalize(S.query.trim());if(!q)return [];return [...channels.map((x,i)=>({...x,kind:'channel',index:i,title:x.name})),...availableMovies().map(x=>({...x,kind:'movie'})),...availableShows().map(x=>({...x,kind:'show'}))].filter(x=>normalize(x.title).includes(q)&&(S.searchType==='Tümü'||S.searchType===({channel:'Kanallar',movie:'Filmler',show:'Diziler'}[x.kind])));}
  function searchResults(){const results=matches();if(!S.query.trim())return '<div class="empty-block"><h2>Ne izlemek istersin?</h2><p>Kanal, film veya dizi adıyla ara.</p></div>';if(!results.length)return `<div class="empty-block"><h2>Sonuç bulunamadı.</h2><p>Başka bir ad veya daha kısa bir kelime dene.</p></div>`;return `<div class="search-count">${results.length} sonuç</div><div class="search-grid">${results.map(item=>item.kind==='channel'?`<button class="search-channel" data-focus="result-${item.id}" data-action="play" data-index="${item.index}">${P.logo(item)}<span>${esc(item.name)}</span><small>Canlı TV</small></button>`:poster(item,item.kind,'result-')).join('')}</div>`;}
  function search(){return `<section class="view shell">${sidebar('search')}<div class="page-body library"><h2>Aradığın burada.</h2><div class="search-box">${icon('search')}<input type="search" data-focus="search-input" id="search-input" value="${esc(S.query)}" placeholder="Kanal, film veya dizi ara" aria-label="İçerik ara" autocomplete="off">${btn('search-keyboard','keyboard',icon('keyboard'),'quiet','aria-label="Ekran klavyesini aç" data-field="query"')}${btn('clear-search','clear-search','Temizle','quiet')}</div><div class="filters">${['Tümü','Kanallar','Filmler','Diziler'].map((name,i)=>`<button class="filter" data-focus="search-filter-${i}" data-action="search-filter" data-value="${name}" aria-pressed="${S.searchType===name}">${name}</button>`).join('')}</div><div id="search-results">${searchResults()}</div></div></section>`;}
  function schedule(index){if(!channels[index].program)return [{start:0,end:120,title:'Yayın bilgisi yok',missing:true}];if(index===0)return [{start:0,end:60,title:'Belgesel kuşağı'},{start:60,end:120,title:'Dünyadan hikâyeler'}];if(index===1)return [{start:0,end:30,title:'Gün özeti'},{start:30,end:90,title:'Akşam kuşağı'},{start:90,end:120,title:'Sıradaki program'}];return [{start:0,end:60,title:programs[index]||'Yayın'},{start:60,end:120,title:'Sıradaki program'}];}
  const scheduleTime=min=>`${20+Math.floor(min/60)}:${String(min%60).padStart(2,'0')}`;
  function guide(){return `<section class="view shell">${sidebar('guide')}<div class="page-body library"><div class="library-head"><h2>Yayın rehberi</h2><span class="badge">ÖRNEK PROGRAM VERİSİ</span></div><p class="guide-subtitle">Bugün · 20:42 <span>Sağlayıcının EPG verisi henüz doğrulanmadı.</span></p><div class="epg-head"><span>Kanallar</span><div><span>20.00</span><span>20.30</span><span>21.00</span><span>21.30</span></div></div><div class="epg-body">${channels.map((ch,i)=>`<div class="epg-row"><div class="epg-channel">${P.logo(ch)}</div><div class="epg-programs">${schedule(i).map((p,j)=>`<button style="width:${(p.end-p.start)/120*100}%" class="epg-program ${p.start<=42&&p.end>42?'now':''}" data-focus="program-${i}-${j}" data-action="program" data-index="${i}" data-program="${j}" data-start="${p.start}" data-end="${p.end}" data-guide-row="${i}"><strong>${esc(p.title)}</strong><span>${p.missing?'Kanala geç':scheduleTime(p.start)+' — '+scheduleTime(p.end)}</span></button>`).join('')}</div></div>`).join('')}</div></div></section>`;}
  function home(){if(S.result==='partial')return `<section class="view shell">${sidebar('home')}<div class="page-body library"><h2>Kanalların hazır.</h2><div class="channel-grid">${channels.map(P.card).join('')}</div>${pendingCatalog()}</div></section>`;const recent=Object.entries(S.history).filter(([,value])=>value.position>5&&value.position<value.duration);return `<section class="view shell">${sidebar('home')}<div class="page-body home full-home"><div class="home-hero real-hero" style="--hero-art:url('${esc(art(hero))}')"><div class="hero-top"><span class="clock">20:42</span><span class="avatar">EV</span></div><div class="hero-copy"><div class="eyebrow">KÜTÜPHANENDEN · FİLM</div><h1>Inception</h1><p>Rüyaların içinde, gerçeğin sınırında.</p><div class="metadata-line">2010 · ${duration(hero)} · ${esc(hero.genre)}</div><div class="actions">${btn('hero-play','hero-play',icon('play')+' İzlemeye başla','primary')}${btn('hero-detail','open-movie','Ayrıntılar','quiet','data-id="m3"')}${btn('all-channels','all-channels','Canlı TV','quiet')}</div></div></div>${recent.length?`<section class="section-block"><div class="section-heading"><h3>İzlemeye devam et</h3></div><div class="continue-grid">${recent.map(([id,h])=>{const item=h.kind==='movie'?findMovie(id):episodeById(id)?.show;if(!item)return '';return `<button class="continue-card" data-focus="continue-${id}" data-action="resume" data-id="${id}"><img src="${esc(art(item))}" alt=""><span>${esc(item.title)}<small>${time(h.position)} / ${time(h.duration)}</small></span><i style="width:${h.position/h.duration*100}%"></i></button>`;}).join('')}</div></section>`:''}<section class="section-block"><div class="section-heading"><h3>Kanalların</h3><span>${sourceName()} · 6 kanal</span></div><div class="channel-grid">${channels.slice(0,5).map(P.card).join('')}</div></section><section class="section-block"><div class="section-heading"><h3>Film seçkisi</h3></div><div class="poster-grid home-posters">${movies.map(x=>poster(x,'movie')).join('')}</div></section><section class="section-block"><div class="section-heading"><h3>Dizilere yer aç</h3></div><div class="poster-grid home-posters">${shows.map(x=>poster(x,'show')).join('')}</div></section></div></section>`;}
  function pinDigit(value){if(value==='del'){S.pin=S.pin.slice(0,-1);renderPanel('pin-del');return;}S.pin+=value;if(S.pin.length===4){if(S.pin==='1234'){const pending=S.pending;S.pinOrigin=null;S.unlocked.add(pending.id);S.pending=null;S.pin='';closePanel();pending.run();announce('Erişim açıldı.');}else{S.pin='';S.pinError='PIN doğru değil. Tekrar dene.';renderPanel('pin-1');announce(S.pinError);}}else{renderPanel('pin-'+value);}}
  P.panels.pin=()=>({title:'PIN kodunu gir',className:'pin-panel',first:'pin-1',body:`<p class="panel-note">Bu içeriğe erişmek için aile PIN kodu gerekiyor.</p><div class="pin-dots" aria-label="${S.pin.length} hane girildi">${[0,1,2,3].map(i=>`<span class="${i<S.pin.length?'filled':''}"></span>`).join('')}</div>${S.pinError?`<p class="error-message" role="alert">${S.pinError}</p>`:''}<div class="pin-grid">${[1,2,3,4,5,6,7,8,9,'del',0,'cancel'].map(n=>btn('pin-'+n,n==='cancel'?'close-panel':'pin-digit',n==='del'?'Sil':n==='cancel'?'İptal':n,'quiet',`data-value="${n}"`)).join('')}</div>`});
  function keyboardValue(){return S.keyboardField==='query'?S.query:S.form[S.keyboardField];}
  function setKeyboardValue(value){if(S.keyboardField==='query')S.query=value;else S.form[S.keyboardField]=value;}
  P.panels.description=()=>{const item=S.view==='movie'?findMovie(S.movieId):findShow(S.showId);return {title:esc(item.title),first:'description-close',body:`<div class="full-description" tabindex="0" data-focus="description-text">${esc(item.description)}</div>${btn('description-close','close-panel','Kapat','quiet')}`};};
  P.panels.keyboard=()=>({title:S.keyboardField==='query'?'İçerik ara':({url:'Bağlantı',name:'Kaynak adı',user:'Kullanıcı adı',pass:'Şifre'}[S.keyboardField]),className:'keyboard-panel',first:'key-0',body:`<div class="keyboard-display" aria-live="polite">${esc(S.keyboardField==='pass'?'•'.repeat(keyboardValue().length):keyboardValue())||'Yazmaya başla…'}</div><div class="keyboard-grid">${[...'abcdefghijklmnopqrstuvwxyz0123456789çğıöşü.:/@_-?=&'].map((x,i)=>btn('key-'+i,'key',esc(x),'quiet',`data-value="${esc(x)}"`)).join('')}</div><div class="actions keyboard-actions">${btn('key-space','key','Boşluk','quiet','data-value=" "')}${btn('key-delete','key-delete','Sil','quiet')}${btn('key-clear','key-clear','Temizle','quiet')}${btn('key-done','key-done','Tamam','primary')}</div>`});
  P.panels.program=()=>({title:S.program.title,dialog:true,first:'watch-program',body:`<p>${esc(channels[S.program.channel].name)} · ${scheduleTime(S.program.start)} — ${scheduleTime(S.program.end)}<br>${S.program.start>42?'Bu program henüz başlamadı.':'Geçmiş yayın bu kaynakta doğrulanmadı.'} Mevcut kanala geçebilirsin.</p><div class="actions">${btn('watch-program','watch-program','Canlı kanala geç','primary')}${btn('program-close','close-panel','Kapat','quiet')}</div>`});
  P.panels.finished=()=>{const next=nextEpisode();return {title:next?'Sonraki bölüme hazır mısın?':S.media.kind==='episode'?'Önizlemedeki bölümler tamamlandı.':'Film tamamlandı.',dialog:true,first:next?'play-next':'finished-back',body:`<p>${next?`${esc(next.title)}<br><span id="next-timer">${S.nextSeconds}</span> saniye sonra başlayacak.`:'İzleme ilerlemen bu oturum için kaydedildi.'}</p><div class="actions">${next?btn('play-next','vod-next','Şimdi oynat','primary'):btn('finished-back','leave-vod','Ayrıntıya dön','primary')}${btn('cancel-next','cancel-next',next?'Otomatik geçişi iptal et':'Oynatıcıda kal','quiet')}</div>`};};
  P.panels.settings=()=>({title:'Ayarlar',first:'motion',body:`<h3>Görünüm</h3><button class="track" role="switch" aria-checked="${S.reduced}" data-focus="motion" data-action="motion"><span>Hareketi azalt</span><span>${S.reduced?'Açık':'Kapalı'}</span></button><h3>Aile</h3><button class="track" data-focus="parental" data-action="parental" role="switch" aria-checked="${S.parental}"><span>PIN koruması</span><span>${S.parental?'Açık':'Kapalı'}</span></button><h3>Kaynak</h3><p class="panel-note">${sourceName()} · ${S.method==='m3u'?'M3U':'Xtream Codes'} örneği</p><div class="actions">${btn('refresh-source','refresh-source','Yenile','quiet')}${btn('change-source','change-source','Kaynak ekle','quiet')}</div><p class="panel-note">Bu denemede veriler yalnız bu oturumda tutulur.</p>`});
  P.panels['stream-error']=()=>({title:'Yayın şu an açılamıyor.',dialog:true,first:'retry-stream',body:`<p>Bağlantı kesilmiş veya yayın geçici olarak kullanılamıyor olabilir.</p><div class="actions">${btn('retry-stream','retry-stream','Tekrar dene','primary')}${btn('error-channels','error-channels',S.view==='vod'?'Ayrıntıya dön':'Kanallara dön','quiet')}</div>`});
  Object.assign(P.views,{home,movies:()=>catalog('movie'),series:()=>catalog('show'),movie:()=>detail('movie'),show:()=>detail('show'),vod,search,guide,favorites});
  Object.assign(P.focusRules,{home:()=> 'hero-play',movies:()=>{const x=catalogItems('movie')[0];return x?'movie-'+x.id:S.result==='partial'?'pending-retry':'catalog-filter-'+Math.max(0,['Tümü','Açık içerikler','Korumalı'].indexOf(S.catalogFilter));},series:()=>{const x=catalogItems('show')[0];return x?'show-'+x.id:S.result==='partial'?'pending-retry':'catalog-filter-'+Math.max(0,['Tümü','Açık içerikler','Korumalı'].indexOf(S.catalogFilter));},movie:()=> 'detail-play',show:()=> 'show-continue',vod:()=>S.controls?'vod-toggle':'reveal',search:()=> 'search-input',guide:()=> 'program-0-0',favorites:()=> 'fav-filter-'+['Kanallar','Filmler','Diziler'].indexOf(S.favType)});
  const oldPlay=P.actions.play,oldRetry=P.actions['retry-stream'];
  Object.assign(P.actions,{
    reveal:()=>{if(S.view==='vod'){S.controls=true;render('vod-toggle');}else P.showControls();},
    description:()=>openPanel('description'),
    'close-panel':()=>{if(S.panel==='pin')cancelPin();else if(S.panel==='keyboard'){closePanel();render(S.view==='search'?'search-input':'field-'+S.keyboardField);}else closePanel();},
    'switch-channel':el=>{const index=Number(el.dataset.index);gate(channels[index],()=>{S.channel=index;S.controls=true;S.panel=null;render('channels');announce(P.c().name+' seçildi.');});},
    'hero-play':()=>playMovie('m3'), 'open-movie':el=>openDetail('movie',el.dataset.id,el.dataset.focus),'open-show':el=>openDetail('show',el.dataset.id,el.dataset.focus),
    'catalog-filter':el=>{S.catalogFilter=el.dataset.value;render(el.dataset.focus);},'detail-back':()=>go(S.detailReturn.view,S.detailReturn.focus),
    'play-movie':el=>playMovie(el.dataset.id),'restart-movie':()=>playMovie(S.movieId,true),'play-episode':el=>playEpisode(el.dataset.id),'show-continue':()=>{const ep=firstResumeEpisode();if(ep)playEpisode(ep.id);else toast('Bu dizide bölüm bulunmuyor.');},
    season:el=>{S.season=Number(el.dataset.value);render(el.dataset.focus);},'catalog-favorite':el=>{const id=el.dataset.id;S.favorites.has(id)?S.favorites.delete(id):S.favorites.add(id);render(el.dataset.focus);toast(S.favorites.has(id)?'Favorilerine eklendi':'Favorilerinden çıkarıldı');},
    'fav-filter':el=>{S.favType=el.dataset.value;render(el.dataset.focus);},'favorite-browse':()=>go(S.favType==='Filmler'?'movies':S.favType==='Diziler'?'series':'live'),
    'search-filter':el=>{S.searchType=el.dataset.value;render(el.dataset.focus);},'clear-search':()=>{S.query='';render('search-input');},
    keyboard:el=>{S.keyboardField=el.dataset.field||S.keyboardField;openPanel('keyboard');},key:el=>{setKeyboardValue(keyboardValue()+el.dataset.value);renderPanel(el.dataset.focus);},'key-delete':()=>{setKeyboardValue([...keyboardValue()].slice(0,-1).join(''));renderPanel('key-delete');},'key-clear':()=>{setKeyboardValue('');renderPanel('key-clear');},'key-done':()=>{closePanel();render(S.view==='search'?'search-input':'field-'+S.keyboardField);},
    program:el=>{const i=Number(el.dataset.index),program=schedule(i)[Number(el.dataset.program)];if(program.missing||program.start<=42&&program.end>42)P.play(i,el.dataset.focus);else{S.program={...program,channel:i};openPanel('program');}},'watch-program':()=>{const i=S.program.channel,origin=S.panelOpener;closePanel();P.play(i,origin);},
    'pin-digit':el=>pinDigit(el.dataset.value),parental:()=>{if(S.parental){requestPin({id:'settings-parental',run:()=>{S.parental=false;openPanel('settings');}});}else{S.parental=true;S.unlocked.clear();renderPanel('parental');}},
    'leave-vod':leaveVod,'vod-toggle':()=>{if(S.media.position>=S.media.duration)S.media.position=0;S.playing=!S.playing;render('vod-toggle');},'vod-seek':el=>{S.media.position=Math.max(0,Math.min(S.media.duration,S.media.position+Number(el.dataset.value)));saveProgress();render(el.dataset.focus);},
    'vod-next':()=>{const next=nextEpisode();if(next){clearInterval(nextTimer);playEpisode(next.id);}},'cancel-next':()=>{clearInterval(nextTimer);closePanel();S.controls=true;render('vod-toggle');},resume:el=>{const h=S.history[el.dataset.id];if(h.kind==='movie')playMovie(el.dataset.id);else playEpisode(el.dataset.id);},
    'refresh-source':()=>{closePanel();toast('Örnek kaynak güncellendi.');},'retry-stream':()=>{oldRetry();if(S.view==='vod'){S.playing=true;render('vod-toggle');}},'error-channels':()=>{if(S.view==='vod')leaveVod();else{S.panel=null;go('live','row-'+P.c().id);}}
  });
  P.hooks.beforePlay=(index,origin)=>{const item=channels[index];if(locked(item)){gate(item,()=>P.play(index,origin));return false;}return true;};
  P.hooks.activeTracks=()=>S.view==='vod'?{audio:[['tr','Türkçe · 5.1'],['en','İngilizce · 5.1']],subs:[['en-1','İngilizce 1'],['en-2','İngilizce 2']]}:null;
  P.hooks.back=()=>{if(S.panel==='keyboard'){closePanel();render(S.view==='search'?'search-input':'field-'+S.keyboardField);return true;}if(S.panel==='pin'){cancelPin();return true;}if(S.panel==='finished'){clearInterval(nextTimer);closePanel();render('vod-toggle');return true;}if(S.panel)return false;if(S.view==='vod'){if(S.controls){S.controls=false;render('reveal');}else leaveVod();return true;}if(['movie','show'].includes(S.view)){go(S.detailReturn.view,S.detailReturn.focus);return true;}if(['movies','series','search','guide'].includes(S.view)){const id='nav-'+S.view;if(document.activeElement?.dataset.focus===id)go('home','nav-home');else focus(id);return true;}return false;};
  P.hooks.keydown=event=>{const el=document.activeElement;if(S.panel==='pin'&&/^\d$/.test(event.key)){event.preventDefault();pinDigit(event.key);return true;}if(S.view==='vod'&&!S.controls&&!S.panel&&event.key.startsWith('Arrow')){event.preventDefault();S.controls=true;render('vod-toggle');return true;}if(S.view==='form'&&el.dataset.field&&event.key==='Enter'){event.preventDefault();S.keyboardField=el.dataset.field;openPanel('keyboard');return true;}if(S.view==='search'&&el.id==='search-input'&&event.key==='Enter'){event.preventDefault();const target=app.querySelector('#search-results [data-focus]');if(target)focus(target.dataset.focus);else{S.keyboardField='query';openPanel('keyboard');}return true;}if(S.view==='guide'&&el.dataset.guideRow!==undefined&&['ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const row=Number(el.dataset.guideRow)+(event.key==='ArrowUp'?-1:1);if(row>=0&&row<channels.length){const programs=schedule(row),index=programs.findIndex(p=>p.start<=S.guideAnchor&&p.end>S.guideAnchor);focus(`program-${row}-${Math.max(index,0)}`);}return true;}return false;};
  function realLivePreview(){if(!['live','favorites'].includes(S.view))return;const image=app.querySelector('.preview-art');if(image){image.style.backgroundImage='none';image.innerHTML=`<div class="large-channel-logo">${P.logo(channels[S.preview])}</div><span class="badge">PROGRAM VERİSİ ÖRNEKTİR</span>`;}app.querySelectorAll('.channel-row').forEach(el=>{const ch=channels[Number(el.dataset.index)];if(ch?.logo){const mini=el.querySelector('.mini-logo');if(mini)mini.innerHTML=`<img src="${esc(ch.logo)}" alt="">`;}if(ch?.locked&&!el.querySelector('.row-lock')){const badge=document.createElement('span');badge.className='row-lock';badge.textContent='PIN';el.append(badge);}});}
  const baseAfter=P.hooks.afterRender;
  P.hooks.afterRender=()=>{baseAfter?.();app.classList.toggle('missing-art',S.missingArt);if(S.view==='player'){const player=app.querySelector('.player');player.style.backgroundImage='none';const box=document.createElement('div');box.className='live-placeholder';box.innerHTML=`${P.logo(P.c())}<span>Canlı oynatıcı önizlemesi</span>`;player.insertBefore(box,player.firstChild);player.querySelector('.sample-watermark').textContent='Örnek oynatma · gerçek video yok';}if(S.view==='form'){const actions=app.querySelector('.form-fields .actions');if(actions&&!app.querySelector('[data-focus=form-keyboard]'))actions.insertAdjacentHTML('beforeend',btn('form-keyboard','keyboard',icon('keyboard'),'quiet','aria-label="Ekran klavyesini aç"'));}realLivePreview();};
  app.addEventListener('focusin',event=>{if(event.target.dataset.field)S.keyboardField=event.target.dataset.field;if(event.target.dataset.start!==undefined){const start=Number(event.target.dataset.start),end=Number(event.target.dataset.end);S.guideAnchor=Math.max(start,Math.min(end-1,S.guideAnchor));}realLivePreview();});
  app.addEventListener('input',event=>{if(event.target.id==='search-input'){S.query=event.target.value;document.getElementById('search-results').innerHTML=searchResults();announce(matches().length+' sonuç');}if(event.target.id==='vod-seek'){S.media.position=Number(event.target.value);saveProgress();document.getElementById('vod-current').textContent=time(S.media.position);}});
  app.addEventListener('error',event=>{if(event.target.tagName==='IMG'){event.target.style.visibility='hidden';event.target.parentElement.classList.add('art-missing');}},true);
  document.getElementById('finish-episode').addEventListener('click',()=>{if(S.view==='vod')finish();else announce('Önce bir film veya bölüm aç.');});
  document.getElementById('missing-art').addEventListener('change',event=>{S.missingArt=event.target.checked;app.classList.toggle('missing-art',S.missingArt);render(P.defaultFocus());});
  if(new URLSearchParams(location.search).get('preview')==='home')S.view='home';
  render();
})();
